/// Set an order's client_order_id when absent (or 0) and return it.
fn fill_client_order_id(order: &mut m::OrderInput, ids: &dyn ClientOrderIdProvider) -> u64 {
    let meta = order.metadata.get_or_insert_with(Default::default);
    if meta.client_order_id.unwrap_or(0) == 0 {
        meta.client_order_id = Some(ids.next_id());
    }
    meta.client_order_id.unwrap_or(0)
}

